SELECT e.* FROM medical_equipment e LEFT JOIN department d ON e.department_id = d.id WHERE 1 = 1
AND e.category = #{category}
AND e.status = #{status}
AND (LOWER(e.equipment_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(e.equipment_code) LIKE LOWER(CONCAT('%', #{keyword}, '%')))
ORDER BY e.id DESC

